/**
 * NAYAN AI 3D Eye Journey - Main Orchestrator
 * Entry point connecting Three.js EyeScene, GSAP ScrollController,
 * LoadingManager, Navigation, and Interactive Landing Page components.
 */

import { EyeScene } from './eye-scene.js';
import { ScrollController } from './scroll-controller.js';
import { LoadingManager } from './loading-manager.js';
import { Navigation } from './navigation.js';
import { Interactions } from './interactions.js';
import { SectionsManager } from './sections.js';

class App {
  constructor() {
    this.eyeScene = null;
    this.scrollController = null;
    this.navigation = null;
    this.interactions = null;
    this.sections = null;

    this.init();
  }

  init() {
    // 1. Navigation & UI
    this.navigation = new Navigation();
    this.interactions = new Interactions();
    this.sections = new SectionsManager();

    // 2. Loading Manager
    const canvasContainer = document.getElementById('webgl-canvas-container');
    const loadingManager = new LoadingManager(() => {
      console.log('NAYAN AI 3D Eye Journey ready.');
      if (this.scrollController) {
        this.scrollController.refresh();
      }
    });

    loadingManager.start();

    // 3. Initialize Three.js 3D Scene
    try {
      if (canvasContainer) {
        this.eyeScene = new EyeScene(canvasContainer, () => {
          // Initialize ScrollTrigger when 3D scene & authentic photo assets are loaded
          this.scrollController = new ScrollController(this.eyeScene);
        });

        if (!this.eyeScene.isWebGLAvailable) {
          this._handleWebGLFallback();
        }
      }
    } catch (err) {
      console.error('Three.js scene initialization error:', err);
      loadingManager.showError('Could not initialize 3D scene. Displaying accessible medical layout.');
      this._handleWebGLFallback();
    }
  }

  _handleWebGLFallback() {
    const fallbackBanner = document.getElementById('webgl-fallback-banner');
    if (fallbackBanner) fallbackBanner.style.display = 'block';

    const canvasContainer = document.getElementById('webgl-canvas-container');
    if (canvasContainer) canvasContainer.classList.add('fallback-mode');
  }
}

// Boot application when DOM is ready
window.addEventListener('DOMContentLoaded', () => {
  window.NayanApp = new App();
});
